<script setup lang="ts">
import { computed, onScopeDispose, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { api, asApiError, ApiError } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { formatFen, shanghaiTime } from '../domain/m1';
import { frozen, type ReceiptRequest } from '../domain/m3';
import { useSessionStore } from '../stores/session';
import ErrorPanel from '../components/ErrorPanel.vue';
import StatusBadge from '../components/StatusBadge.vue';
const route=useRoute();const session=useSessionStore();const id=computed(()=>String(route.params.attemptId));
const checkout=useRemote(async()=>{const expected=id.value;const value=await api.getMockCheckout(expected);if(value.attempt.id!==expected||value.purchaseId!==value.attempt.purchaseId)throw new ApiError('INVALID_RESPONSE','Mock 付款页关联不符。');return {checkout:value,payment:await api.getPaymentStatus(value.purchaseId)};});
const outcome=ref<ReceiptRequest['outcome']>('PAID');const confirmation=ref(false);const pending=ref(false);const error=ref<ApiError|null>(null);const notice=ref('');let revision=0;let signature='';let key='';
const isFrozen=computed(()=>checkout.data.value&&(frozen(checkout.data.value.checkout.attempt.state)||frozen(checkout.data.value.payment.state)));
const canComplete=computed(()=>session.can('payments.manual')&&checkout.data.value?.checkout.canComplete&&!isFrozen.value&&checkout.data.value.payment.state!=='PAID'&&checkout.data.value.checkout.attempt.state!=='FAILED'&&checkout.data.value.checkout.attempt.state!=='PAID');
watch(()=>[route.fullPath,session.user?.currentTenantId,session.user?.userId],()=>{revision++;confirmation.value=false;pending.value=false;error.value=null;notice.value='';outcome.value='PAID';signature='';key='';void checkout.load();},{immediate:true,flush:'sync'});onScopeDispose(()=>revision++);
async function simulate(){
 if(pending.value||!confirmation.value||!canComplete.value||!checkout.data.value)return;
 const current=revision;const attemptId=id.value;const body={outcome:outcome.value};const next=JSON.stringify({attemptId,...body});if(next!==signature){signature=next;key=globalThis.crypto.randomUUID();}pending.value=true;error.value=null;
 try{await api.simulatePaymentReceipt(attemptId,body,key);if(current!==revision)return;confirmation.value=false;notice.value='合成回执已提交。回执仅作为线索；后台独立查验账号、采购号、金额、币种与权威状态后才能确认 Mock 已付。';await checkout.load();}
 catch(cause){if(current===revision)error.value=asApiError(cause);}
 finally{if(current===revision)pending.value=false;}
}
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">支付中心 / 本地演示</p><h1>本地 Mock 回执模拟器</h1><p class="muted">合成状态测试 · 无真实收银台、支付或平台授权</p></div><div class="inline-actions"><RouterLink class="text-link" to="/payments/queue">返回付款队列</RouterLink><el-button :disabled="pending" :loading="checkout.loading.value" @click="checkout.load">刷新权威状态</el-button></div></div><div class="freeze-note"><h2>此页面仅模拟付款回执</h2><p>不填写任何账号密码、支付密码、验证码或银行卡。点击模拟不会直接把采购单标记为已付；后台先做独立权威查验。</p></div><div v-if="checkout.loading.value" class="panel data-state" role="status"><el-skeleton :rows="5" animated /><p>正在读取已登录租户的 Mock 付款尝试…</p></div><ErrorPanel v-else-if="checkout.error.value" :error="checkout.error.value" title="Mock 付款页不可用"><el-button @click="checkout.load">重试读取</el-button></ErrorPanel><section v-else-if="checkout.data.value" class="panel detail-panel"><div class="panel-heading"><div><h2>Mock 人工付款尝试</h2><p class="mono">{{ id }}</p></div><StatusBadge kind="payment" :status="checkout.data.value.payment.state" /></div><div v-if="isFrozen" class="freeze-note" role="status"><h2>正在核实，请勿再次付款</h2><p>所有回执模拟与付款入口已冻结。返回队列可申请只读查单。</p></div><dl class="order-facts"><div><dt>采购单</dt><dd><RouterLink class="text-link mono" :to="`/purchases/${checkout.data.value.checkout.purchaseId}`">{{ checkout.data.value.checkout.purchaseId }}</RouterLink></dd></div><div><dt>Mock 付款金额 · CNY</dt><dd class="detail-money">{{ formatFen(checkout.data.value.checkout.totalFen) }}</dd></div><div><dt>合成权威流水状态</dt><dd>{{ checkout.data.value.checkout.authorityState }} · {{ checkout.data.value.checkout.authorityState==='UNPAID'?'权威未付':checkout.data.value.checkout.authorityState==='PAID'?'合成流水已付，仍以独立查验结果为准':'合成流水失败' }}</dd></div><div><dt>入口有效至（上海）</dt><dd>{{ shanghaiTime(checkout.data.value.checkout.expiresAt) }}</dd></div><div><dt>付款尝试状态</dt><dd class="mono">{{ checkout.data.value.checkout.attempt.state }}</dd></div><div><dt>后台已核验状态</dt><dd><StatusBadge kind="payment" :status="checkout.data.value.payment.state" /></dd></div></dl><form v-if="canComplete" class="inline-form" @submit.prevent="confirmation=true"><label>合成回执结果<select v-model="outcome" name="receiptOutcome" :disabled="pending"><option value="PAID">PAID · 模拟已付线索</option><option value="UNPAID">UNPAID · 模拟未付</option><option value="FAILED">FAILED · 模拟明确失败</option></select></label><el-button data-testid="simulate-receipt" native-type="submit" type="primary" :disabled="pending">模拟回执</el-button></form><p v-else-if="!isFrozen" class="help-text">当前尝试不可提交回执；可能已完成、已过期或身份仅有查看权限。请刷新核对。</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p><ErrorPanel v-if="error&&!confirmation" :error="error" /></section><el-dialog v-if="confirmation" v-model="confirmation" title="确认提交合成 Mock 回执" width="500px" :close-on-click-modal="false" :close-on-press-escape="!pending" :show-close="!pending"><p>合成结果 {{ outcome }}，不会产生真实扣款。</p><p class="help-text">回执仅作为线索。UNPAID 保持待商家付款；UNKNOWN 保持冻结，不允许重复付款。后台需独立核对权威状态。</p><ErrorPanel v-if="error" :error="error" /><template #footer><el-button :disabled="pending" @click="confirmation=false">取消</el-button><el-button data-testid="confirm-receipt" type="primary" :loading="pending" :disabled="pending||!canComplete" @click="simulate">确认模拟回执</el-button></template></el-dialog></div></template>
